#include "PluginEditor.h"
MiraForgeAudioProcessorEditor::MiraForgeAudioProcessorEditor(MiraForgeAudioProcessor&q):AudioProcessorEditor(&q),p(q){setSize(620,260);title.setText("MIRAFORGE",juce::dontSendNotification);title.setFont(juce::Font(30.f,juce::Font::bold));addAndMakeVisible(title);preset.setJustificationType(juce::Justification::centred);preset.setFont(juce::Font(19.f));addAndMakeVisible(preset);count.setJustificationType(juce::Justification::centred);addAndMakeVisible(count);for(auto*b:{&prev,&next,&random}){addAndMakeVisible(b);b->onClick=[this,b]{if(b==&prev)p.setPresetIndex(p.getPresetIndex()-1);else if(b==&next)p.setPresetIndex(p.getPresetIndex()+1);else p.setPresetIndex(juce::Random::getSystemRandom().nextInt(250000));};}startTimerHz(10);}void MiraForgeAudioProcessorEditor::paint(juce::Graphics&g){g.fillAll(juce::Colour(0xff0b0b10));g.setColour(juce::Colour(0xff242431));g.fillRoundedRectangle(24,76,572,130,18,18);g.setColour(juce::Colour(0xff6f63ff));g.fillRoundedRectangle(46,98,528,5,3);g.setColour(juce::Colours::white);g.setFont(14.f);g.drawText("ORIGINAL PROCEDURAL SYNTH • 250,000 VARIATIONS",46,168,528,24,juce::Justification::centred);g.setColour(juce::Colour(0xff9b96aa));g.drawText("ARPS • KEYS • BELLS • PLUCKS • PADS • GUITAR-LIKE TEXTURES • BASS",46,190,528,20,juce::Justification::centred);}void MiraForgeAudioProcessorEditor::resized(){title.setBounds(24,16,572,42);preset.setBounds(45,108,530,34);count.setBounds(210,52,200,20);prev.setBounds(55,220,55,28);next.setBounds(510,220,55,28);random.setBounds(235,220,150,28);}void MiraForgeAudioProcessorEditor::timerCallback(){preset.setText(p.getPresetName(),juce::dontSendNotification);count.setText(juce::String(p.getPresetIndex()+1)+" / 250,000",juce::dontSendNotification);}
